def dtype_predicate(dtype, dtypes_set) -> bool:
    # Import necessary modules
    import numpy as np
    from pandas.core.dtypes.dtypes import ArrowDtype, is_bool_dtype
    from pandas.core.dtypes.base import ExtensionDtype

    # Check if dtype is a subtype of ExtensionDtype
    if isinstance(dtype, ExtensionDtype):
        if isinstance(dtype, ArrowDtype):
            # If ArrowDtype, convert to numpy dtype
            dtype = dtype.numpy_dtype
        else:
            # Handle other ExtensionDtype logic if needed
            dtype = dtype.type

    # Main predicate logic
    return (
        issubclass(dtype.type, tuple(dtypes_set))
        or (
            np.number in dtypes_set
            and getattr(dtype, "_is_numeric", False)
            and not is_bool_dtype(dtype)
        )
        or (dtype.type in [str, np.object_] and np.object_ in dtypes_set)
    )
